	sections = {
		{
			title = "Summary",
			text = [=[Azshara is a land of red autumn woods, broken cliffs and drowned ruins on the north-eastern coast of {link:kalimdor}Kalimdor{/link}, east of {link:ashenvale}Ashenvale{/link} and south of {link:winterspring}Winterspring{/link}. It bears the name of {link:queen-azshara}Queen Azshara{/link}, and it wears her memory like a wound. Shattered temples lean over the {link:bay-of-storms}Bay of Storms{/link}, the columns of old cities lie half-sunk in the surf, and the spirits of the {link:high-elves}Highborne{/link} still drift among the stones. Few people come here willingly. Those who do come for what the ruins still hide.]=],
		},
		{
			title = "Origins",
			text = [=[No chronicle records the year when the Highborne first built upon these shores. What is known is that in the age before the {link:great-sundering}Great Sundering{/link} this was a country of their cities and temples, and that its greatest mages wrote the laws of the arcane upon tablets and runes for all to read. When the {link:well-of-eternity}Well of Eternity{/link} was destroyed at the end of the {link:war-of-the-ancients}War of the Ancients{/link}, the land was torn apart. Much of the city of {link:ruins-of-eldarath}Eldarath{/link} fell into the sea, and the coast became the jagged thing it is today. The queen and her servants were lost beneath the waves. The night elves who survived turned their backs on this place, and for ten thousand years they have shunned it.]=],
		},
		{
			title = "The Present Day",
			text = [=[Azshara belongs to no one, and everyone wants something from it. The {link:naga}naga{/link} of the Spitelash have come back out of the sea to claim the ruins of their ancestors. {link:satyrs}Satyrs{/link} of the {link:haldarr-encampment}Haldarr{/link} and the Legashi haunt the woods. A company of blood elves under the mage {link:magus-rimtori}Rimtori{/link} has camped on the northern bluffs to dig for Highborne treasures. The {link:horde}Horde{/link} holds a small, bloodied outpost at {link:valormok}Valormok{/link}, and the {link:sentinels}Sentinels{/link} keep watch from {link:talrendis-point}Talrendis Point{/link} on the border of {link:ashenvale}Ashenvale{/link}. A human archmage keeps a tower in the western hills, a demon hunter lives on an island in the bay, and a blue dragon guards the southern woods. In the north, behind a great gate that no outsider has passed, furbolgs struggle against a corruption rising from the depths.]=],
		},
		{
			title = "Inhabitants",
			text = [=[• {b}The Spitelash {link:naga}naga{/link}.{/b} They hold the {link:ruins-of-eldarath}Ruins of Eldarath{/link}, the beaches and the reefs, and their warlord rules from the {link:temple-of-zin-malor}Temple of Zin-Malor{/link}.
• {b}The satyrs.{/b} The {link:haldarr-encampment}Haldarr{/link} clan lurks near {link:valormok}Valormok{/link}, and the Legashi hold the northern woods.
• {b}The blood elves.{/b} Surveyors and reclaimers serve {link:magus-rimtori}Magus Rimtori{/link}, who hunts for the relics of the Highborne.
• {b}The furbolgs of the north.{/b} They guard the gate of {link:blackmaw-hold}Blackmaw Hold{/link} and let no stranger near it.
• {b}The cliff giants.{/b} They wander the southern hills and eat the very stone of the land.
• {b}The blue dragonflight.{/b} {link:azuregos}Azuregos{/link} and the dragonspawn keep watch over the old magic of the coast.
• {b}The makrura.{/b} The crab-folk of the {link:temple-of-arkkoran}Temple of Arkkoran{/link} worship their master, {link:lord-arkkoroc}Lord Arkkoroc{/link}.
• {b}The restless dead.{/b} Highborne apparitions haunt the western shrines, bound to the arcane they loved.]=],
		},
		{
			title = "History",
			text = [=[• {b}The Age of the Highborne.{/b} {link:ruins-of-eldarath}Eldarath{/link} flourished, and its mages gave their lives to the study of {link:arcane-magic}the arcane{/link}.
• {b}The {link:great-sundering}Sundering{/link}.{/b} The Well imploded, the land broke, and the sea swallowed half of Eldarath.
• {b}The Long Silence.{/b} For ten thousand years the ruins were left to spirits, beasts and the tides.
• {b}The Present Day.{/b} The {link:naga}naga{/link} have returned from the deep. Treasure-seekers of every race have followed them.]=],
		},
		{
			title = "Lore of the Coast",
			text = [=[• The cliff giants of the south devour rock and ruin alike. What passes through them hardens into azsharite, a crystal both supple and very strong.
• The blood elves call a goblin who once worked for them "{link:kim-jael}Kim'jael{/link}". He swears it means "little rat", and he has not forgiven them.
• The tablets of {link:ruins-of-eldarath}Eldarath{/link} are named for four Highborne wizards: Beth'{link:moon-priestess-amara}Amara{/link}, Jin'yael, Markri and Sael'hai.]=],
		},
	},
})

