			text = [=[Archmage Xylem is a human mage who has made his home in a tower high in the hills above {link:azshara}Azshara{/link}. Visitors must first find his servant {link:sanath-lim-yo}Sanath Lim-yo{/link}, who sends them up to the tower by magic. Xylem is proud, cold and very powerful. He is human, as {link:jediga}Jediga{/link} of {link:valormok}Valormok{/link} says, but he acts like no human she has ever met.]=],
		},
		{
			title = "Significance",
			text = [=[Xylem came to {link:azshara}Azshara{/link} for the same reason as everyone else: its magic. He buys the knowledge of the Highborne, harvests the enchanted coral of the bay, and watches the land through scrying spells. Even the rogue lord {link:lord-jorach-ravenholdt}Jorach Ravenholdt{/link} turns to him when an enchantment must be broken.]=],
		},
		{
			title = "Deeds",
			text = [=[• He pays {link:jediga}Jediga{/link} for the Tablet of Sael'hai from the {link:ruins-of-eldarath}Ruins of Eldarath{/link}.
• He sent an apprentice to trade with the blood elves for their glittering dust, and the blood elves killed the apprentice.
• He works to break the enchantment on a sealed azure bag for Lord {link:ravenholdt-manor}Ravenholdt{/link}.
• He sends a hunter after {link:warlord-krellian}Warlord Krellian{/link} and the prismatic shell the {link:naga}naga{/link} covets.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle records where Xylem came from, why he chose {link:azshara}Azshara{/link}, or what he means to do with all he gathers.]=],
		},
	},
	chapters = {
		{
			key = "the-tablet-of-sael-hai",
			title = "The Tablet of Sael'hai",
			hint = "Deliver the last of Jediga's tablets to the archmage.",
			unlock = {
				{ type = "quest", id = 3561 },
			},
			text = [=[{link:jediga}Jediga{/link} warned that Xylem was the most dangerous of all her buyers. He took the tablet and paid exactly as he had promised. That surprised her more than any betrayal would have.]=],
		},
		{
			key = "the-old-nemesis",
			title = "The Old Nemesis",
			hint = "Avenge the archmage's apprentice in the sunken temple.",
			unlock = {
				{ type = "quest", id = 8253 },
			},
			text = [=[Years ago the green drake {link:morphaz}Morphaz{/link} ambushed Xylem and swallowed one of his apprentices whole. Xylem did not grieve the apprentice. He grieved the arcane shard the apprentice carried. When the shard was cut from the drake's belly in the {link:temple-of-atal-hakkar}Temple of Atal'Hakkar{/link}, it had grown with the drake's power. With it, the archmage's full craft was restored.]=],
