	sections = {
		{
			title = "Summary",
			text = [=[Duke Hydraxis is an elemental lord of water who dwells on an island off the eastern coast of {link:azshara}Azshara{/link}. He commands the Hydraxian Waterlords. He bears within him an aspect of Neptulon, the great lord of the tides, and he wages an old war against the lesser {link:elements}Elements{/link}: air, earth and above all fire.]=],
		},
		{
			title = "Significance",
			text = [=[Hydraxis is one of the few elemental powers that will treat with mortals. He does so for his war. He cares nothing for the {link:alliance}Alliance{/link} or the {link:horde}Horde{/link}, only for the purity of water and for the defeat of fire. In mortals willing to fight, he sees the chance of a true alliance.]=],
		},
		{
			title = "Deeds",
			text = [=[• He seeks to cure the elementals of water that the plague of {link:lordaeron}Lordaeron{/link} has twisted.
• He sends his allies against the servants of air and earth in the {link:the-crystal-vale}Crystal Vale{/link} of {link:silithus}Silithus{/link}.
• He seeks the defeat of the servants of fire who hold {link:blackrock-mountain}Blackrock Mountain{/link}.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle of mortals records how long Hydraxis has kept his island, or why the Waterlords chose {link:azshara}Azshara{/link}.]=],
		},
	},
	chapters = {
		{
			key = "poisoned-water",
			title = "Poisoned Water",
			hint = "Help the Waterlords restore their tainted kin.",
			unlock = {
				{ type = "quest", id = 6804 },
			},
			text = [=[A force of water elementals went into the {link:eastern-plaguelands}Eastern Plaguelands{/link} and came back sick. For the Waterlords, such a thing was an outrage. Hydraxis gave a vial of Neptulon's own essence to cure them. The cure could not quiet the madness that followed.]=],
