	sections = {
		{
			title = "Summary",
			text = [=[Azuregos is a great blue dragon who keeps watch over southern {link:azshara}Azshara{/link}. The shores here are rich in old magic, and the ruins still hold the relics of the Highborne. Azuregos is here to keep them from mortal hands. He does not hide what he is. He will warn intruders away, and then he will fight them.]=],
		},
		{
			title = "Significance",
			text = [=[The blue dragonflight has always guarded the world's magic from those who would misuse it. That a dragon as mighty as Azuregos keeps his post in {link:azshara}Azshara{/link} says much about what may lie hidden here. Some whisper that the fabled Vials of Eternity themselves may have been found in these woods.

The treasure-seekers who crowd into Azshara, blood elves, {link:naga}naga{/link}, goblins and archmages alike, all come for the same magic that he guards. Sooner or later, each of them must reckon with the dragon.]=],
		},
		{
			title = "Deeds",
			text = [=[• He guards the magical treasures of {link:azshara}Azshara{/link} against all comers.
• He studies the magic-rich shores of the coast, seeking whatever the {link:great-sundering}Sundering{/link} left behind.
• Blue dragonspawn, magelords and mageweavers of his flight keep watch over the land under his eye.]=],
		},
		{
			title = "Unrecorded",
			text = [=[No chronicle records when Azuregos came to {link:azshara}Azshara{/link}, or exactly what he guards. It is said that the blue dragons have watched over the ruins of {link:ruins-of-eldarath}Eldarath{/link} for many generations, but whether Azuregos has been among them from the start, none can say.]=],
		},
	},
	bonds = {
		{ id = "queen-azshara", name = "Queen Azshara", note = "the queen whose relics he guards" },
	},
})

